def set_cell(cell, text, bold=False, size=8):
 cell.text=''; p=cell.paragraphs[0]; p.alignment=WD_ALIGN_PARAGRAPH.CENTER
 r=p.add_run(str(text)); r.bold=bold; r.font.name='Times New Roman'; r.font.size=Pt(size)
 cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER

def table(doc, df, caption, maxrows=None, size=7):
 p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=p.add_run(caption); r.bold=True; r.font.size=Pt(10)
 d=df if maxrows is None else df.head(maxrows)
 t=doc.add_table(rows=1, cols=len(d.columns)); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.style='Table Grid'
 for j,c in enumerate(d.columns): set_cell(t.rows[0].cells[j],c,True,size)
 for _,row in d.iterrows():
  cells=t.add_row().cells
  for j,v in enumerate(row): set_cell(cells[j], f'{v:.4f}' if isinstance(v,float) else v,False,size)
 return t

def para(doc,text,style=None):
 p=doc.add_paragraph(style=style); p.paragraph_format.first_line_indent=Inches(.35); p.paragraph_format.line_spacing=1.5; p.paragraph_format.space_after=Pt(6); p.add_run(text); return p

